package com.jnapanam.sportszone.identity.controller;import com.jnapanam.sportszone.identity.dto.*;import com.jnapanam.sportszone.identity.service.PasswordRecoveryService;import io.swagger.v3.oas.annotations.security.SecurityRequirements;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/auth/password")@SecurityRequirements public class PasswordRecoveryController{private final PasswordRecoveryService service;public PasswordRecoveryController(PasswordRecoveryService service){this.service=service;}@PostMapping("/forgot")public ResponseEntity<ForgotPasswordResponse>forgot(@Valid@RequestBody ForgotPasswordRequest request){return ResponseEntity.accepted().body(service.forgot(request));}@PostMapping("/reset")@ResponseStatus(HttpStatus.NO_CONTENT)public void reset(@Valid@RequestBody ResetPasswordRequest request){service.reset(request);}}
